import{_ as e,a as d,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Catalog Categories — Datagrid Listing (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-categories-list","title":"List Catalog Categories (Datagrid)","description":"Cursor-paginated query returning the flat category list — the GraphQL equivalent of the admin Catalog → Categories datagrid. Supports filtering by name, status, position, parent_id, and locale.","query":"query AdminCatalogCategories(\\n  $first: Int\\n  $after: String\\n  $name: String\\n  $status: Int\\n  $locale: String\\n) {\\n  adminCategories(\\n    first: $first\\n    after: $after\\n    name: $name\\n    status: $status\\n    locale: $locale\\n  ) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        name\\n        slug\\n        description\\n        status\\n        position\\n        parentId\\n        displayMode\\n        locale\\n        logoUrl\\n        bannerUrl\\n        createdAt\\n        updatedAt\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      hasPreviousPage\\n      endCursor\\n      startCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"name\\": \\"Apparel\\",\\n  \\"status\\": 1,\\n  \\"locale\\": \\"en\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCategories\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/catalog/categories/7\\",\\n            \\"_id\\": 7,\\n            \\"name\\": \\"Apparel\\",\\n            \\"slug\\": \\"apparel\\",\\n            \\"description\\": \\"<p>Clothing and accessories for every season.</p>\\",\\n            \\"status\\": 1,\\n            \\"position\\": 1,\\n            \\"parentId\\": 1,\\n            \\"displayMode\\": \\"products_and_description\\",\\n            \\"locale\\": \\"en\\",\\n            \\"logoUrl\\": null,\\n            \\"bannerUrl\\": null,\\n            \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n            \\"updatedAt\\": \\"2026-04-30T14:20:09+00:00\\"\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": false,\\n        \\"hasPreviousPage\\": false,\\n        \\"endCursor\\": \\"MA==\\",\\n        \\"startCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/categories/categories-listing.md","filePath":"api/graphql-api/admin/catalog/categories/categories-listing.md","lastUpdated":1787725411000}'),r={name:"api/graphql-api/admin/catalog/categories/categories-listing.md"};function n(c,t,i,s,l,g){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="catalog-categories-—-datagrid-listing-graphql" tabindex="-1">Catalog Categories — Datagrid Listing (GraphQL) <a class="header-anchor" href="#catalog-categories-—-datagrid-listing-graphql" aria-label="Permalink to &quot;Catalog Categories — Datagrid Listing (GraphQL)&quot;">​</a></h1><p>Cursor-paginated GraphQL query that mirrors the Bagisto admin <strong>Catalog → Categories</strong> datagrid. Returns the flat category list with filtering, sorting, and cursor pagination.</p><p>For the flat-list versus tree shapes, hierarchy and move semantics, and display modes, see the <a href="/api/graphql-api/admin/catalog/categories/">Categories overview</a>.</p><p>This query returns a <strong>flat, cursor-paginated list</strong>, which is what a datagrid needs. For the nested hierarchy behind a tree picker use <a href="/api/graphql-api/admin/catalog/categories/categories-tree.html"><code>adminCategoryTrees</code></a> instead.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Pagination</th></tr></thead><tbody><tr><td><code>adminCategories</code></td><td>Query</td><td>Cursor (<code>first</code> / <code>after</code>)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>first</code></td><td><code>Int</code></td><td>Number of items per page (default <code>10</code>, max <code>50</code>)</td><td><code>10</code></td></tr><tr><td><code>after</code></td><td><code>String</code></td><td>Cursor from a previous <code>pageInfo.endCursor</code> for keyset pagination</td><td><code>&quot;MA==&quot;</code></td></tr><tr><td><code>last</code></td><td><code>Int</code></td><td>Page size when paging backwards</td><td><code>10</code></td></tr><tr><td><code>before</code></td><td><code>String</code></td><td>Cursor from a previous <code>pageInfo.startCursor</code></td><td><code>&quot;MA==&quot;</code></td></tr><tr><td><code>category_id</code></td><td><code>String</code></td><td>Filter by category ID — single integer or comma-separated list (e.g. <code>&quot;12&quot;</code> or <code>&quot;12,18&quot;</code>)</td><td><code>&quot;7&quot;</code></td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Partial category name match (SQL <code>LIKE %value%</code>)</td><td><code>&quot;Apparel&quot;</code></td></tr><tr><td><code>position</code></td><td><code>Int</code></td><td>Exact position filter</td><td><code>1</code></td></tr><tr><td><code>status</code></td><td><code>Int</code></td><td>Filter by status: <code>0</code> = disabled, <code>1</code> = enabled</td><td><code>1</code></td></tr><tr><td><code>parent_id</code></td><td><code>Int</code></td><td>Filter by parent category ID</td><td><code>1</code></td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale code for translation resolution (default: app locale)</td><td><code>&quot;en&quot;</code></td></tr><tr><td><code>sort</code></td><td><code>String</code></td><td>Column to sort by (see Sorting section below)</td><td><code>&quot;id&quot;</code></td></tr><tr><td><code>order</code></td><td><code>String</code></td><td>Sort direction: <code>&quot;asc&quot;</code> or <code>&quot;desc&quot;</code> (default <code>&quot;desc&quot;</code>)</td><td><code>&quot;desc&quot;</code></td></tr></tbody></table><p>Every filter is a first-class GraphQL argument — pass them alongside <code>first</code> and <code>after</code>, not inside a nested filter object. Filters combine with AND, so each one narrows the result. Note that <code>category_id</code>, <code>parent_id</code>, <code>sort</code>, and <code>order</code> are snake_case or single words while the rest are camelCase; that is the literal schema.</p><h2 id="node-fields" tabindex="-1">Node Fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node Fields&quot;">​</a></h2><p>Each <code>edges[].node</code> object contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>API Platform IRI (e.g. <code>/api/admin/catalog/categories/7</code>)</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Raw category ID</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Category name resolved via <code>locale</code></td></tr><tr><td><code>slug</code></td><td><code>String</code></td><td>URL slug</td></tr><tr><td><code>status</code></td><td><code>Int</code></td><td><code>1</code> = enabled, <code>0</code> = disabled</td></tr><tr><td><code>position</code></td><td><code>Int</code></td><td>Display order position</td></tr><tr><td><code>parentId</code></td><td><code>Int</code></td><td>Parent category ID; <code>null</code> for root nodes</td></tr><tr><td><code>description</code></td><td><code>String</code></td><td>Category description, HTML, resolved via <code>locale</code></td></tr><tr><td><code>displayMode</code></td><td><code>String</code></td><td>Category display mode (e.g. <code>products_and_description</code>)</td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale used for name/slug/description resolution</td></tr><tr><td><code>logoUrl</code></td><td><code>String</code></td><td>Storage URL for the category logo; <code>null</code> if not set</td></tr><tr><td><code>bannerUrl</code></td><td><code>String</code></td><td>Storage URL for the category banner; <code>null</code> if not set</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td><code>String</code></td><td>ISO 8601 last-update timestamp</td></tr></tbody></table><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Pass <code>sort</code> with the column name and <code>order</code> for direction. The compound form <code>sort: &quot;name-asc&quot;</code> is also accepted (splits on <code>-</code>).</p><p><strong>Sortable columns:</strong></p><table tabindex="0"><thead><tr><th><code>sort</code> value</th><th>Sorts by</th></tr></thead><tbody><tr><td><code>id</code></td><td>Category ID (default)</td></tr><tr><td><code>name</code></td><td>Category name</td></tr><tr><td><code>position</code></td><td>Display order position</td></tr><tr><td><code>status</code></td><td>Enabled/disabled status</td></tr></tbody></table><h2 id="cursor-pagination" tabindex="-1">Cursor Pagination <a class="header-anchor" href="#cursor-pagination" aria-label="Permalink to &quot;Cursor Pagination&quot;">​</a></h2><ul><li><code>first</code> controls the page size (default <code>10</code>, max <code>50</code>).</li><li>To fetch the next page, pass the <code>pageInfo.endCursor</code> value as <code>after</code> in the next request.</li><li><code>totalCount</code> reflects the full count of matching categories across all pages.</li></ul><h2 id="fields-that-stay-null-on-the-listing" tabindex="-1">Fields That Stay Null on the Listing <a class="header-anchor" href="#fields-that-stay-null-on-the-listing" aria-label="Permalink to &quot;Fields That Stay Null on the Listing&quot;">​</a></h2><p><code>translations</code> and <code>filterableAttributeIds</code> are declared on the type but resolve only on the item query <a href="/api/graphql-api/admin/catalog/categories/categories-detail.html"><code>adminCategory(id:)</code></a>. Selecting them here is not an error — you simply get <code>null</code>.</p><h2 id="behaviour-worth-knowing" tabindex="-1">Behaviour Worth Knowing <a class="header-anchor" href="#behaviour-worth-knowing" aria-label="Permalink to &quot;Behaviour Worth Knowing&quot;">​</a></h2><ul><li><strong>No implicit status filter.</strong> Every status is returned so an admin can find a disabled category. Pass <code>status: 1</code> for enabled only.</li><li><strong><code>parent_id</code> returns direct children only</strong>, not the whole subtree. For a full branch use <a href="/api/graphql-api/admin/catalog/categories/categories-tree.html"><code>adminCategoryTrees</code></a> with <code>rootId</code>.</li><li><strong>Scalars are real types here.</strong> <code>status</code>, <code>position</code>, <code>parentId</code>, and <code>_id</code> come back as <code>Int</code>, unlike the product listing, where the same concepts are strings. Timestamps are ISO 8601 with offset.</li><li><strong>REST returns the same rows</strong> through <code>GET /api/admin/catalog/categories</code>, with identical filter and sort semantics.</li></ul>',22)]))}const p=e(r,[["render",n]]);export{u as __pageData,p as default};
